    medication_preferences TEXT NOT NULL DEFAULT '',
    complementary_therapy_preferences TEXT NOT NULL DEFAULT '',
    other_treatment_wishes TEXT NOT NULL DEFAULT '',
    preferred_language VARCHAR(100) NOT NULL DEFAULT '',
    communication_aids TEXT NOT NULL DEFAULT '',
    how_to_share_information TEXT NOT NULL DEFAULT '',
    who_to_involve_in_decisions TEXT NOT NULL DEFAULT '',
    information_sharing_restrictions TEXT NOT NULL DEFAULT '',
    preferred_communication_style TEXT NOT NULL DEFAULT '',
    primary_contact_name VARCHAR(255) NOT NULL DEFAULT '',
    primary_contact_relationship VARCHAR(100) NOT NULL DEFAULT '',
    primary_contact_phone VARCHAR(30) NOT NULL DEFAULT '',
    primary_contact_email VARCHAR(255) NOT NULL DEFAULT '',
    secondary_contact_name VARCHAR(255) NOT NULL DEFAULT '',
    secondary_contact_relationship VARCHAR(100) NOT NULL DEFAULT '',
    secondary_contact_phone VARCHAR(30) NOT NULL DEFAULT '',
    people_who_should_visit TEXT NOT NULL DEFAULT '',
    people_who_should_not_visit TEXT NOT NULL DEFAULT '',
    support_network_details TEXT NOT NULL DEFAULT '',
    financial_arrangements TEXT NOT NULL DEFAULT '',
    property_arrangements TEXT NOT NULL DEFAULT '',
    insurance_details TEXT NOT NULL DEFAULT '',
    will_location TEXT NOT NULL DEFAULT '',
    has_lasting_power_of_attorney VARCHAR(5) NOT NULL DEFAULT '' CHECK (has_lasting_power_of_attorney IN ('yes', 'no', '')),
    lpa_details TEXT NOT NULL DEFAULT '',
    funeral_wishes TEXT NOT NULL DEFAULT '',
    burial_or_cremation VARCHAR(20) NOT NULL DEFAULT '' CHECK (burial_or_cremation IN ('burial', 'cremation', 'other', '')),
    other_practical_matters TEXT NOT NULL DEFAULT '',
    maker_signature_obtained VARCHAR(5) NOT NULL DEFAULT '' CHECK (maker_signature_obtained IN ('yes', 'no', '')),
    maker_signature_date DATE,
    witness_name VARCHAR(255) NOT NULL DEFAULT '',
    witness_address TEXT NOT NULL DEFAULT '',
